  function fullPriceBreakdown(o){const f=orderFinance(o);return financeRow("Menu item value",f.subtotal)+financeRow("Discount",-f.discount)+(f.delivery?financeRow("Delivery fee",f.delivery):"")+(f.rain?financeRow("Rain fee",f.rain):"")+(f.surge?financeRow("Surge fee",f.surge):"")+(f.small?financeRow("Small-order fee",f.small):"")+(f.late?financeRow("Late-night fee",f.late):"")+(f.platform?financeRow("Platform fee",f.platform):"")+(f.tax?financeRow("Tax",f.tax):"")+(f.tip?financeRow("Checkout rider tip",f.tip):"")+'<div class="divider"></div>'+financeRow("Customer total",f.total)+'<div class="notice info">'+icon("shield","small")+'<span>Restaurant, rider and platform settlement activity is derived from ledger journals. Open Recent finance for the bounded ledger window.</span></div>'}
  function moneyPaise(value){const paise=Number(value);return Number.isSafeInteger(paise)?new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",minimumFractionDigits:0,maximumFractionDigits:2}).format(paise/100):"Not available"}
