  function ledgerWindowLabel(){const finance=state.dashboardFinance;if(!finance)return"Ledger window unavailable";if(!finance.oldestOccurredAt||!finance.newestOccurredAt)return"No journals in the recent bounded window";return dateTime(finance.oldestOccurredAt)+" to "+dateTime(finance.newestOccurredAt)}
  function financeCompletenessWarning(){const finance=state.dashboardFinance;if(!finance||finance.complete!==false)return"";return'<div class="notice danger">'+icon("warning","small")+'<span><strong>Financial snapshot incomplete.</strong> '+h(finance.invalidJournalCount)+' invalid journal'+(finance.invalidJournalCount===1?' was':'s were')+' excluded. Do not use this window for financial decisions; retry and investigate the affected journals.</span></div>'}
  function ledgerMovementRows(){const movements=ledgerMovements();return movements.length?movements.map(movement=>'<div class="price-row" style="gap:12px;align-items:flex-start"><span style="min-width:0"><strong style="overflow-wrap:anywhere">'+h(ledgerAccountLabel(movement.id))+'</strong><small class="caption" style="display:block;overflow-wrap:anywhere">'+h(movement.id)+'</small></span><strong class="'+(movement.amount>=0?'success':'')+'" style="flex:0 0 auto">'+h(moneyPaise(movement.amount))+'</strong></div>').join(""):'<p class="supporting">No valid signed account movements were returned in this recent window.</p>'}
  function ledgerEventRows(){const events=state.dashboardFinance&&state.dashboardFinance.eventCounts||{},keys=Object.keys(events).sort((a,b)=>Number(events[b])-Number(events[a])||a.localeCompare(b));return keys.length?keys.map(key=>'<div class="price-row"><span>'+h(key.replace(/[-_]+/g," "))+'</span><strong>'+h(Number(events[key]||0))+'</strong></div>').join(""):'<p class="supporting">No ledger events were returned in this recent window.</p>'}
  function awaitingVerifiedPayment(o){return o&&o.paymentMethod!=="cod"&&o.paymentState!=="paid"&&o.paymentState!=="refunded"}
  function screenFinanceReport(){const finance=state.dashboardFinance,movements=ledgerMovements();return'<main class="screen"><div class="content page">'+top("Recent finance","Signed activity from a bounded ledger window")+banner()+financeCompletenessWarning()+'<section class="card hero stack"><p class="supporting" style="color:rgba(255,255,255,.8)">RECENT BOUNDED LEDGER WINDOW</p><strong class="display">'+h(finance?finance.journalCount:0)+' valid journals</strong><p class="supporting" style="color:rgba(255,255,255,.8)">'+h(ledgerWindowLabel())+'</p></section><section class="metric-grid">'+metric("VALID JOURNALS",finance?finance.journalCount:0,"Maximum 100 recent valid journals")+metric("INVALID JOURNALS",finance?finance.invalidJournalCount:0,finance&&finance.complete===false?"Snapshot incomplete":"None excluded",finance&&finance.complete===false?"danger":"")+metric("ACCOUNTS TOUCHED",movements.length,"Signed activity in this window")+metric("EVENT TYPES",finance?Object.keys(finance.eventCounts||{}).length:0,"Within this recent window")+'</section><div class="notice warning">'+icon("warning","small")+'<span>Values are bounded signed activity only. They must not be treated as account balances, restaurant payables, COD figures, payout due or proof of settlement.</span></div><section class="card stack"><div><h2 class="section-title">Signed account activity</h2><p class="supporting">Only server-returned <code>windowNetMovementPaise</code> activity is shown, with credit-positive and debit-negative signs preserved.</p></div>'+ledgerMovementRows()+'</section><section class="card stack"><div><h2 class="section-title">Ledger events</h2><p class="supporting">Counts in the same bounded window.</p></div>'+ledgerEventRows()+'</section>'+(state.loading?loading("Refreshing ledger window…"):"")+'</div>'+nav()+'</main>'}
  function dashboardOrder(o){return'<article class="card order-row"><div class="order-head"><div><div class="cluster wrap"><span class="status '+statusTone(o.status)+'">'+h(o.status)+'</span><span class="caption sla">'+h(ago(o.createdAt))+'</span></div><h3 class="card-title" style="margin-top:9px">'+h(o.restaurant||"Restaurant")+' · '+h(o.id)+'</h3><p class="supporting">'+h(o.customerName||"Customer")+' · '+money(o.total)+'</p></div><button class="icon-button flat" data-action="open-order" data-order-id="'+h(o.id)+'" aria-label="Open order">'+icon("chevron")+'</button></div>'+(o.status==="Ready for pickup"&&!o.riderId?'<div class="notice warning">'+icon("riders","small")+'<span>Restaurant marked this ready; rider assignment is required.</span></div>':o.status==="Order placed"&&awaitingVerifiedPayment(o)?'<div class="notice warning">'+icon("warning","small")+'<span>Customer online payment is still '+h(o.paymentState||"pending")+'. Restaurant acceptance stays locked until payment is verified.</span></div>':o.status==="Order placed"?'<div class="notice info">'+icon("clock","small")+'<span>Waiting for the restaurant to accept this order.</span></div>':'')+'</article>'}
  function supportActivityAt(t){return Math.max(Number(t&&t.createdAt||0),Number(t&&t.updatedAt||0),Number(t&&t.customerUpdatedAt||0),Number(t&&t.lastCustomerMessageAt||0),Number(t&&t.lastCustomerReplyAt||0))}
  function supportActivityKey(t){return supportActivityAt(t)+":"+hash([t&&t.message,t&&t.reason,t&&t.assistantTranscript,t&&t.aiSummary,t&&t.customerMessageCount,t&&t.lastCustomerMessageId].map(v=>String(v||"")).join("|"))}
  function supportNeedsAttention(t){if(!t||t.status==="closed")return false;const activityAt=supportActivityAt(t),seenAt=Number(t.seenAt||0);if(!seenAt)return true;if(activityAt>seenAt)return true;return !!t.seenActivityKey&&t.seenActivityKey!==supportActivityKey(t)}
  function unseenSupport(){return flattenNested(state.support).filter(supportNeedsAttention)}
  function supportAlarmKey(t){return [t.uid||t.userId||"",t.id||"",supportActivityKey(t)].join(":")}
