      +'<section class="metric-grid">'+metric("ACTIVE ORDERS",activeOrders().length,"Up to 100 in bounded live view")+metric("VALID JOURNALS",finance?finance.journalCount:0,"Recent bounded activity window")+metric("ACCOUNTS TOUCHED",ledgerAccountCount,"Signed activity; not balances")+metric("READY / UNASSIGNED",ready.length,ready.length?"Dispatch required":"No queue","warning")+metric("APPROVED RIDERS",approved.length,Object.keys(state.riders||{}).filter(id=>state.riders[id]&&state.riders[id].status==="approved"&&riderAvailable(id)).length+" marked online")+'</section>'
