  function filteredOrders(){let list=state.orders.slice(),q=state.query;if(state.orderFilter==="active")list=list.filter(o=>typeof o.active==="boolean"?o.active:!TERMINAL.has(o.status));else if(state.orderFilter==="new")list=list.filter(o=>o.status==="Order placed");else if(state.orderFilter==="kitchen")list=list.filter(o=>["Accepted","Preparing"].includes(o.status));else if(state.orderFilter==="ready")list=list.filter(o=>["Ready for pickup","Assigned"].includes(o.status));else if(state.orderFilter==="delivery")list=list.filter(o=>["Handed to rider","Out for delivery","Near you","Arrived"].includes(o.status));else if(state.orderFilter==="closed")list=list.filter(o=>typeof o.active==="boolean"?!o.active:TERMINAL.has(o.status));if(searchKey(q))list=list.filter(o=>searchMatches([o.id,o.restaurant,o.customerName,o.customerPhone,(o.items||[]).map(i=>i.name).join(" ")].join(" "),q));return list}
  function orderRow(o){const elapsed=Math.floor((Date.now()-Number(o.createdAt||Date.now()))/60000),itemCount=orderItemCount(o);return'<article class="card order-row" data-order-id="'+h(o.id)+'"><div class="order-head"><div class="grow"><div class="cluster wrap"><span class="status '+statusTone(o.status)+'">'+h(o.status)+'</span><span class="caption sla '+(elapsed>45&&!TERMINAL.has(o.status)?'danger':'')+'">'+elapsed+' min</span></div><h2 class="card-title" style="margin-top:9px">'+h(o.restaurant||"Restaurant")+' · '+h(o.id)+'</h2><p class="supporting">'+h(o.customerName||"Customer")+' · '+h(itemCount)+' item'+(itemCount===1?'':'s')+' · '+money(o.total)+(awaitingVerifiedPayment(o)?' · payment pending':'')+'</p></div><button class="icon-button flat" data-action="open-order" data-order-id="'+h(o.id)+'">'+icon("chevron")+'</button></div><div class="row-actions">'+(o.status==="Ready for pickup"&&!o.riderId?'<span class="status">Smart dispatch active</span>':'')+'<button class="button tonal small" data-action="open-order" data-order-id="'+h(o.id)+'">Details</button></div></article>'}
