  function restaurantRow(r,id){const image=safeImage(r.imageUrl||r.image),menu=Array.isArray(r.menu)?r.menu:[],rating=Number(r.rating||0),ratingCount=Number(r.ratingCount||0);return'<article class="card entity-row" data-action="edit-restaurant" data-restaurant-id="'+h(id)+'" style="cursor:pointer"><div class="entity-image" style="display:grid;place-items:center;overflow:hidden">'+(image?'<img src="'+h(image)+'" alt="" style="width:100%;height:100%;object-fit:cover">':icon("restaurant","large"))+'</div><div class="grow"><div class="cluster wrap"><h2 class="card-title">'+h(r.name||"Untitled restaurant")+'</h2><span class="status '+(r.open!==false&&!r.archived?'success':r.archived?'danger':'warning')+'">'+(r.archived?'Archived':r.open!==false?'Accepting orders':'Paused')+'</span></div><p class="supporting">'+h((Array.isArray(r.cuisines)?r.cuisines:[]).join(" · ")||r.address||"Details incomplete")+'</p><p class="caption">'+menu.filter(i=>!i.archived).length+' menu items · '+h(r.etaMin||25)+'–'+h(r.etaMax||35)+' min · '+(ratingCount?rating.toFixed(1)+' ★ from '+ratingCount:'New · no ratings yet')+'</p></div><button class="icon-button flat" data-action="edit-restaurant" data-restaurant-id="'+h(id)+'">'+icon("chevron")+'</button></article>'}
  function filteredRestaurants(){const q=state.restaurantQuery;return Object.keys(state.catalog||{}).map(id=>Object.assign({id},state.catalog[id]||{})).filter(r=>!searchKey(q)||searchMatches([r.name,r.id,r.phone,r.city,r.category,r.address,restaurantOwnerEmail(r),(r.cuisines||[]).join(" "),(r.menu||[]).map(i=>[i.name,i.category,i.description].join(" ")).join(" ")].join(" "),q)).sort((a,b)=>Number(a.archived)-Number(b.archived)||String(a.name).localeCompare(String(b.name)))}
  function restaurantResultsMarkup(){const list=filteredRestaurants();return list.length?'<div class="entity-list">'+list.map(r=>restaurantRow(r,r.id)).join("")+'</div>':empty("search","No matching restaurant","Search checks names, owner emails, menu items, city, cuisine and address.","clear-restaurant-search","Clear search")}
  function screenRestaurants(){const all=Object.keys(state.catalog||{});return'<main class="screen"><div class="content page">'+banner()+'<header class="cluster between"><div><p class="eyebrow">Catalogue</p><h1 class="title">Restaurants and menus.</h1><p class="supporting">'+(owner()?"Owner-only publishing and availability controls.":"Read-only catalogue for your assigned restaurant.")+'</p></div>'+(owner()?'<button class="button primary small" data-action="new-restaurant">'+icon("plus")+' Add</button>':'')+'</header>'+(all.length?'<div class="input-wrap"><span class="input-icon">'+icon("search")+'</span><input id="restaurant-search" class="input with-icon" value="'+h(state.restaurantQuery)+'" placeholder="Search restaurant, owner, city or menu" autocomplete="off" enterkeyhint="search" aria-label="Search restaurants"></div><div id="restaurant-results">'+restaurantResultsMarkup()+'</div>':empty("restaurant","No restaurants published","Create the first restaurant, add its location and publish its menu.",owner()?"new-restaurant":"","Add restaurant"))+(owner()&&!all.length?'<button class="button tonal full" data-action="publish-starter">Publish a starter record</button>':'')+'</div>'+nav()+'</main>'}
