  function validRiderPayoutResult(raw,request){const value=callableValue(raw);if(!value||typeof value!=="object"||Array.isArray(value)||value.operationId!==request.operationId||value.riderId!==request.riderId||value.amountPaise!==request.amountPaise||value.method!==request.method||value.status!=="completed"||!Number.isSafeInteger(value.remainingPayablePaise)||value.remainingPayablePaise<0||!Number.isSafeInteger(value.paidEarningsPaise)||value.paidEarningsPaise<0||!Number.isSafeInteger(value.paidTipsPaise)||value.paidTipsPaise<0||typeof value.ledgerJournalId!=="string"||!value.ledgerJournalId.trim()||!Number.isSafeInteger(value.completedAt)||value.completedAt<=0||!["upi","imps","neft"].includes(String(value.recommendedMethod||""))||typeof value.beneficiaryLabel!=="string"||!value.beneficiaryLabel.trim()||typeof value.idempotent!=="boolean")throw new Error("RIDER_PAYOUT_INVALID_RESPONSE");return value}
