  function screenRiders(){
    if(!owner())return'<main class="screen"><div class="content page">'+top("Delivery partners","Owner-only identity and approval workspace")+'<div class="notice warning">'+icon("lock","small")+'<span>Your restaurant staff role cannot access partner identity documents, approvals or COD controls.</span></div></div>'+nav()+'</main>';
    const all=Object.keys(state.riders||{}).map(id=>Object.assign({id},state.riders[id]||{})),pending=all.filter(r=>["submitted","under_review"].includes(r.status)),approved=all.filter(r=>r.status==="approved"),changes=all.filter(r=>r.status==="rejected");
    return'<main class="screen"><div class="content page">'+banner()+'<header class="cluster between"><div><p class="eyebrow">Partner verification</p><h1 class="title">Trusted riders, reviewed carefully.</h1><p class="supporting">Sensitive documents remain owner-only and screenshot-protected.</p></div><button class="icon-button" data-action="refresh">'+icon("refresh")+'</button></header><section class="metric-grid">'+metric("NEEDS REVIEW",pending.length,"Submitted applications","warning")+metric("APPROVED",approved.length,"Eligible for orders","success")+metric("CHANGES",changes.length,"Returned to applicant")+'</section>'+codExposureSection()+'<section class="stack"><h2 class="section-title">Review queue</h2>'+(pending.length?'<div class="entity-list">'+pending.map(r=>riderRow(r,r.id)).join("")+'</div>':empty("riders","No applications waiting","New partner applications will appear after secure submission."))+'</section><section class="stack"><h2 class="section-title">Approved partners</h2>'+(approved.length?'<div class="entity-list">'+approved.map(r=>riderRow(r,r.id)).join("")+'</div>':empty("riders","No approved partners","Approved partners will appear here."))+'</section></div>'+nav()+'</main>'
  }
  function screenRiderReview(){const id=state.selectedRiderId,r=state.riders[id];if(!r)return screenRiders();return'<main class="screen"><div class="content page">'+top(r.fullName||"Partner application",r.email||"",'<span class="status '+(r.status==="approved"?'success':r.status==="rejected"?'danger':'warning')+'">'+h(r.status||"submitted")+'</span>')+'<section class="card form-grid"><h2 class="section-title">Identity and contact</h2><div class="cluster between"><span>Name</span><strong>'+h(r.fullName||"")+'</strong></div><div class="cluster between"><span>Mobile</span><strong>'+h(r.phone||"")+'</strong></div><div class="cluster between"><span>City</span><strong>'+h(r.city||"")+'</strong></div><div class="cluster between"><span>Aadhaar</span><strong>Masked · ending '+h(r.aadhaarLast4||"")+'</strong></div><div class="cluster between"><span>PAN</span><strong>'+h(r.panNumber||"")+'</strong></div></section><section class="card form-grid"><h2 class="section-title">Vehicle</h2><div class="cluster between"><span>Type</span><strong>'+h(r.vehicleType||"")+'</strong></div><div class="cluster between"><span>Registration</span><strong>'+h(r.vehicleNumber||"")+'</strong></div><p class="supporting">'+h(r.address||"")+'</p></section><section class="card stack"><div class="cluster between"><h2 class="section-title">Protected documents</h2><button class="button secondary small" data-action="load-rider-docs" data-rider-id="'+h(id)+'">Review documents</button></div><div id="rider-documents"><div class="notice warning">'+icon("shield","small")+'<span>Documents are loaded only after an explicit owner action. Do not photograph or share them.</span></div></div></section><div class="row-actions">'+(r.status!=="approved"?'<button class="button success grow" data-action="approve-rider" data-rider-id="'+h(id)+'">Approve partner</button>':'')+'<button class="button danger grow" data-action="reject-rider" data-rider-id="'+h(id)+'">Request changes</button></div></div>'+nav()+'</main>'}

  function restaurantAppRow(app,id){return'<article class="card entity-row"><div class="avatar">'+h(String(app.restaurantName||app.email||"R")[0].toUpperCase())+'</div><div class="grow"><div class="cluster wrap"><h2 class="card-title">'+h(app.restaurantName||"Untitled Restaurant")+'</h2><span class="status '+(app.status==="approved"?'success':app.status==="rejected"?'danger':'warning')+'">'+h(String(app.status||"submitted").replace(/_/g," "))+'</span></div><p class="supporting">'+h(app.ownerName||"Owner")+' · '+h(app.phone||"")+' · '+h(app.city||"")+'</p><p class="caption">Submitted '+h(ago(app.submittedAt))+'</p></div><button class="icon-button flat" data-action="review-restaurant-app" data-app-id="'+h(id)+'">'+icon("chevron")+'</button></article>'}
  function screenRestaurantApplications(){if(!owner())return screenMore();const all=Object.keys(state.restaurantApplications||{}).map(id=>Object.assign({id},state.restaurantApplications[id]||{})),pending=all.filter(r=>["submitted","under_review"].includes(r.status)),approved=all.filter(r=>r.status==="approved"),rejected=all.filter(r=>r.status==="rejected");return'<main class="screen"><div class="content page">'+banner()+'<header class="cluster between"><div><p class="eyebrow">Restaurant Registration</p><h1 class="title">Restaurant Applications</h1><p class="supporting">Review new restaurant registrations and grant owner access.</p></div><button class="icon-button" data-action="refresh">'+icon("refresh")+'</button></header><section class="metric-grid">'+metric("PENDING",pending.length,"Review queue","warning")+metric("APPROVED",approved.length,"Active restaurants","success")+metric("REJECTED",rejected.length,"Declined")+'</section><section class="stack"><h2 class="section-title">Review queue</h2>'+(pending.length?'<div class="entity-list">'+pending.map(r=>restaurantAppRow(r,r.id)).join("")+'</div>':empty("restaurant","No pending applications","New restaurant registrations will appear here for review."))+'</section><section class="stack"><h2 class="section-title">Approved restaurants</h2>'+(approved.length?'<div class="entity-list">'+approved.map(r=>restaurantAppRow(r,r.id)).join("")+'</div>':empty("restaurant","No approved applications","Approved applications will appear here."))+'</section></div>'+nav()+'</main>'}
  function screenRestaurantAppReview(){const app=state.restaurantApplications&&state.restaurantApplications[state.selectedRestaurantAppId];if(!app)return screenRestaurantApplications();return'<main class="screen"><div class="content page">'+top(app.restaurantName||"Restaurant application",app.email||"",'<span class="status '+(app.status==="approved"?'success':app.status==="rejected"?'danger':'warning')+'">'+h(app.status||"submitted")+'</span>')+'<section class="card form-grid"><h2 class="section-title">Owner & Contact Details</h2><div class="cluster between"><span>Restaurant Name</span><strong>'+h(app.restaurantName||"")+'</strong></div><div class="cluster between"><span>Owner Name</span><strong>'+h(app.ownerName||"")+'</strong></div><div class="cluster between"><span>Email</span><strong>'+h(app.email||"")+'</strong></div><div class="cluster between"><span>Mobile Phone</span><strong>'+h(app.phone||"")+'</strong></div><div class="cluster between"><span>City</span><strong>'+h(app.city||"")+'</strong></div><div class="cluster between"><span>Cuisines</span><strong>'+h(Array.isArray(app.cuisines)?app.cuisines.join(", "):app.cuisines||"")+'</strong></div></section><section class="card form-grid"><h2 class="section-title">Address</h2><p class="supporting">'+h(app.address||"Address missing")+'</p></section><div class="row-actions">'+(app.status!=="approved"?'<button class="button success grow" data-action="approve-restaurant-app" data-app-id="'+h(app.id)+'">Approve Restaurant Access</button>':'')+'<button class="button danger grow" data-action="reject-restaurant-app" data-app-id="'+h(app.id)+'">Reject Application</button></div></div>'+nav()+'</main>'}
  async function approveRestaurantApp(uidValue){const app=state.restaurantApplications&&state.restaurantApplications[uidValue];if(!app)return;const rid=slug(app.restaurantName||"restaurant")+"-"+uidValue.slice(0,6);try{toast("Approving restaurant access…");const now=Date.now(),restData={id:rid,name:app.restaurantName||"New Restaurant",phone:app.phone||"",address:app.address||"",city:app.city||"",cuisines:Array.isArray(app.cuisines)?app.cuisines:[app.cuisines||"Desserts"],open:false,archived:false,rating:0,ratingCount:0,etaMin:25,etaMax:35,deliveryFee:0,platformFee:12,updatedAt:now},memberData={active:true,email:app.email,name:app.ownerName,permissions:{analytics:true,availability:true,dispatch:true,handover:true,menu:true,orders:true,profile:true,tracking:true},restaurantId:rid,restaurantName:app.restaurantName,role:"restaurant_owner",createdAt:now,createdBy:state.session.email},changes={};changes["catalog/restaurants/"+rid]=restData;changes["restaurantMembers/"+rid+"/"+uidValue]=memberData;changes["userRestaurants/"+uidValue+"/"+rid]=true;changes["restaurantApplications/"+uidValue+"/status"]="approved";changes["restaurantApplications/"+uidValue+"/reviewedAt"]=now;changes["restaurantApplications/"+uidValue+"/reviewedBy"]=state.session.email;await db("PATCH",ROOT,changes);if(state.restaurantApplications[uidValue])state.restaurantApplications[uidValue].status="approved";if(!state.catalog[rid])state.catalog[rid]=restData;toast("Approved "+app.restaurantName+"! Access granted.","success");go("restaurantApplications",{},true)}catch(e){toast("Approval failed. "+friendly(e),"danger")}}
