  function rewardParseConditionGroups(value){return rewardParseJsonArray(value,"Login condition groups").map((group,index)=>{const source=group&&typeof group==="object"&&!Array.isArray(group)?group:{},slots=Array.isArray(source.slots)?source.slots:[];return{groupId:source.groupId?String(source.groupId):undefined,title:String(source.title||("Login Group "+(index+1))).trim(),minimumSlotsRequired:Number(source.minimumSlotsRequired||1),slots:slots.map((slot,slotIndex)=>{const item=slot&&typeof slot==="object"&&!Array.isArray(slot)?slot:{},disabledCities=Array.isArray(item.disabledCityNames)?item.disabledCityNames.map(city=>String(city||"").trim()).filter(Boolean):rewardList(item.disabledCityNames);return{slotId:item.slotId?String(item.slotId):undefined,label:String(item.label||("Slot "+(slotIndex+1))).trim(),startMinute:rewardTimeMinuteLoose(item.startMinute!=null?item.startMinute:item.startTime!=null?item.startTime:item.start),endMinute:rewardTimeMinuteLoose(item.endMinute!=null?item.endMinute:item.endTime!=null?item.endTime:item.end),requiredDurationMinutes:rewardNumericField(item.requiredDurationMinutes),requiredActiveDurationMinutes:rewardNumericField(item.requiredActiveDurationMinutes),requiredOnlinePercentage:rewardNumericField(item.requiredOnlinePercentage!=null?item.requiredOnlinePercentage:item.requiredOnlinePct),minimumOrdersAccepted:rewardNumericField(item.minimumOrdersAccepted),minimumCompletedDeliveries:rewardNumericField(item.minimumCompletedDeliveries),offlineToleranceMinutes:rewardNumericField(item.offlineToleranceMinutes)!=null?rewardNumericField(item.offlineToleranceMinutes):10,gracePeriodMinutes:rewardNumericField(item.gracePeriodMinutes)||0,overlapMode:item.overlapMode==="allow_double_count"?"allow_double_count":"no_double_count",disabledCityNames:disabledCities}}).filter(slot=>slot.startMinute!=null&&slot.endMinute!=null&&slot.label)} }).filter(group=>group.slots.length)}
