  function rewardCampaignEditorSeed(){const dashboard=riderRewardsDashboard(),campaigns=dashboard&&dashboard.campaigns||[],editId=String(state.routeData.campaignId||""),duplicateId=String(state.routeData.duplicateCampaignId||""),source=(campaigns.find(item=>item.campaign&&item.campaign.campaignId===editId)||campaigns.find(item=>item.campaign&&item.campaign.campaignId===duplicateId)||{}).campaign;if(!source)return{campaignId:"",internalName:"",title:"",subtitle:"",description:"",kind:"milestone_bonus",displayType:"weekly_incentive",section:"special",rewardAmountPaise:0,milestones:[],window:"weekly",startAt:Date.now(),endAt:Date.now()+7*86400000,eligibleDays:[0,1,2,3,4,5,6],timeSlots:[],cityNames:[],zoneNames:[],restaurantIds:[],riderIds:[],eligibleRiderTypes:[],vehicleTypes:[],minCompletedTrips:"",minRating:"",firstNCompletedTrips:"",orderTotalMinPaise:"",minimumAccountAgeDays:"",rainOnly:false,requireDailyLoginSession:false,minimumCompletedSessionsPerDay:"",conditionGroups:[],otherConditions:[],milestonePayoutMode:"highest_unlocked",timezone:"Asia/Kolkata",tripAttribution:"delivered_at",allowOverlappingSlotCredit:false,stacking:"stack",priority:100,visible:true,active:true,archived:false,updatedAt:0};const copy=duplicateId&&duplicateId===source.campaignId;return Object.assign({},source,{campaignId:copy?"":source.campaignId,internalName:copy?source.internalName+" copy":source.internalName,title:copy?source.title+" copy":source.title,archived:false,active:copy?false:source.active,updatedAt:copy?0:source.updatedAt})}
