    const timeSlots=(seed.timeSlots||[]).map(t=>({key:uid("ts_"),label:t.label,start:rewardClockValue(t.startMinute),end:rewardClockValue(t.endMinute)}));
    const conditionGroups=(seed.conditionGroups||[]).map(g=>({key:uid("cg_"),groupId:g.groupId||"",title:g.title||"",minimumSlotsRequired:Math.max(1,Number(g.minimumSlotsRequired||1)),slots:(g.slots||[]).map(s=>({key:uid("sl_"),slotId:s.slotId||"",label:s.label||"",start:rewardClockValue(s.startMinute),end:rewardClockValue(s.endMinute),advancedOpen:false,requiredDurationMinutes:s.requiredDurationMinutes||"",requiredActiveDurationMinutes:s.requiredActiveDurationMinutes||"",requiredOnlinePercentage:s.requiredOnlinePercentage||"",minimumOrdersAccepted:s.minimumOrdersAccepted||"",minimumCompletedDeliveries:s.minimumCompletedDeliveries||"",offlineToleranceMinutes:s.offlineToleranceMinutes!=null?s.offlineToleranceMinutes:10,gracePeriodMinutes:s.gracePeriodMinutes||0,overlapMode:s.overlapMode==="allow_double_count"?"allow_double_count":"no_double_count",disabledCityNames:(s.disabledCityNames||[]).join(", ")}))}));
