  function riderRewardFormEl(){return document.getElementById("rider-reward-campaign-form")}
  function rewardHarvestActive(){const form=riderRewardFormEl();if(form&&state.rewardCampaignDraft)harvestRewardCampaignDraft(form)}
  function harvestRewardCampaignDraft(form){
    const d=state.rewardCampaignDraft;if(!d)return;
    const val=name=>form.elements[name]?form.elements[name].value:undefined;
    const checked=name=>form.elements[name]?form.elements[name].checked:undefined;
    d.milestones.forEach(m=>{const t=val("ms_"+m.key+"_target");if(t!==undefined)m.target=t;const r=val("ms_"+m.key+"_reward");if(r!==undefined)m.reward=r;const l=val("ms_"+m.key+"_label");if(l!==undefined)m.label=l});
    d.timeSlots.forEach(t=>{const l=val("ts_"+t.key+"_label");if(l!==undefined)t.label=l;const s=val("ts_"+t.key+"_start");if(s!==undefined)t.start=s;const e=val("ts_"+t.key+"_end");if(e!==undefined)t.end=e});
    d.conditionGroups.forEach(g=>{
      const ti=val("cg_"+g.key+"_title");if(ti!==undefined)g.title=ti;
      const mi=val("cg_"+g.key+"_min");if(mi!==undefined)g.minimumSlotsRequired=Number(mi)||1;
      g.slots.forEach(s=>{
        const p="cg_"+g.key+"_sl_"+s.key+"_";
        const l=val(p+"label");if(l!==undefined)s.label=l;
        const st=val(p+"start");if(st!==undefined)s.start=st;
        const en=val(p+"end");if(en!==undefined)s.end=en;
        const rd=val(p+"reqDuration");if(rd!==undefined)s.requiredDurationMinutes=rd;
        const rad=val(p+"reqActiveDuration");if(rad!==undefined)s.requiredActiveDurationMinutes=rad;
        const rop=val(p+"reqOnlinePct");if(rop!==undefined)s.requiredOnlinePercentage=rop;
        const mo=val(p+"minOrders");if(mo!==undefined)s.minimumOrdersAccepted=mo;
        const md=val(p+"minDeliveries");if(md!==undefined)s.minimumCompletedDeliveries=md;
        const ot=val(p+"offlineTolerance");if(ot!==undefined)s.offlineToleranceMinutes=ot;
        const gr=val(p+"grace");if(gr!==undefined)s.gracePeriodMinutes=gr;
        const ov=val(p+"overlap");if(ov!==undefined)s.overlapMode=ov;
        const dc=val(p+"disabledCities");if(dc!==undefined)s.disabledCityNames=dc
      })
    });
    d.otherConditions.forEach(c=>{const en=checked("oc_"+c.type+"_enabled");if(en!==undefined)c.enabled=en;const va=val("oc_"+c.type+"_value");if(va!==undefined)c.value=va})
  }
