  function rewardCampaignAudienceSummary(campaign){return[ campaign.cityNames&&campaign.cityNames.length?"Cities: "+campaign.cityNames.join(", "):"", campaign.zoneNames&&campaign.zoneNames.length?"Zones: "+campaign.zoneNames.join(", "):"", campaign.eligibleRiderTypes&&campaign.eligibleRiderTypes.length?"Rider types: "+campaign.eligibleRiderTypes.join(", "):"", campaign.vehicleTypes&&campaign.vehicleTypes.length?"Vehicles: "+campaign.vehicleTypes.join(", "):"", campaign.riderIds&&campaign.riderIds.length?"Specific riders: "+campaign.riderIds.length:"", campaign.minimumAccountAgeDays!=null&&campaign.minimumAccountAgeDays!==""?"Min account age: "+campaign.minimumAccountAgeDays+" days":"", campaign.minRating!=null&&campaign.minRating!==""?"Min rating: "+campaign.minRating:""].filter(Boolean).join(" · ")}
