  function cancelSheet(s){return sheetShell("Cancel order","This is terminal and must include an operational reason.",'<form id="cancel-form" class="form-grid" data-order-id="'+h(s.orderId)+'"><div class="field"><label>Reason</label><select class="select" name="reason"><option>Restaurant unable to fulfil</option><option>Item unavailable</option><option>Customer cancellation approved</option><option>Duplicate order</option><option>Serviceability issue</option></select></div><button class="button danger full" type="submit">Cancel this order</button></form>')}
