  function renderSheet(){const sig=state.sheet?JSON.stringify(state.sheet):"";if(sig===state.lastSheetSignature)return;state.lastSheetSignature=sig;if(!state.sheet){sheetRegion.innerHTML="";return}const s=state.sheet;let html="";if(s.type==="deleteBroadcast")html=sheetShell("Delete notification?","This cannot be undone.",'<div class="stack"><button class="button danger full" data-action="confirm-delete-broadcast" data-id="'+h(s.id)+'">Delete permanently</button><button class="button tonal full" data-action="close-sheet">Keep notification</button></div>');else if(s.type==="reset")html=resetSheet();else if(s.type==="assign")html=assignSheet(s);else if(s.type==="cancel")html=cancelSheet(s);else if(s.type==="menuItem")html=menuItemSheet(s);else if(s.type==="transferOwner")html=transferOwnerSheet(s);else if(s.type==="deleteRestaurant")html=deleteRestaurantSheet(s);else if(s.type==="staff")html=inviteStaffSheet();else if(s.type==="promotion")html=promotionSheet(s);else if(s.type==="customer")html=customerSheet(s);else if(s.type==="rejectRider")html=rejectRiderSheet(s);else if(s.type==="codRemittance")html=codRemittanceSheet(s);else if(s.type==="riderPayout")html=riderPayoutSheet(s);else if(s.type==="restaurantSettlement")html=restaurantSettlementSheet(s);else if(s.type==="signout")html=signoutSheet();else if(s.type==="supportTicket")html=supportTicketSheet(s);else if(s.type==="deleteMenu")html=sheetShell("Delete menu item?","This permanently removes the item from the live menu.",'<div class="stack"><div class="notice danger">'+icon("warning","small")+'<span>Use out-of-stock when the item may return. Permanent deletion cannot be undone.</span></div><button class="button danger full" data-action="confirm-delete-menu" data-restaurant-id="'+h(s.restaurantId)+'" data-item-id="'+h(s.itemId)+'">Delete item permanently</button><button class="button tonal full" data-action="close-sheet">Keep item</button></div>');sheetRegion.innerHTML=html}

  async function writeAudit(action,target,detail){const a=auditRecord(action,target,detail);state.audit[a.id]=a;try{await db("PUT",ROOT+"/audit/"+a.id,a)}catch(_){}return a}
  async function setStatus(orderId,status){const o=order(orderId);if(!o)return;const expected=nextStatus(o);if(status!==expected||!canAdvanceOrder(o,status)){toast("That status is not the next permitted step.","danger");return}if(status==="Assigned"){toast("Choose an available rider to create the assignment safely.","danger");return}if(status==="Handed to rider"&&(!o.riderId||o.riderArrivalVerified!==true)){toast("Verify the assigned rider's restaurant arrival before handover.","danger");return}const previous=o.status,previousUpdated=o.updatedAt,previousHistory=Object.assign({},o.statusHistory||{}),now=Date.now(),eventId="e_"+now+"_"+state.role,event={status,at:now,actorId:state.session.uid,actorRole:state.role};o.status=status;o.updatedAt=now;o.statusHistory=Object.assign({},previousHistory,{[eventId]:event});render({preserve:true});try{
      await cloudStatus(o,status,"")
      await writeAudit("order.status",o.id,previous+" → "+status);if(window.FeastlyAdminNative&&FeastlyAdminNative.vibrateSuccess)try{FeastlyAdminNative.vibrateSuccess()}catch(_){}toast("Order moved to "+status+".","success")
    }catch(e){o.status=previous;o.updatedAt=previousUpdated;o.statusHistory=previousHistory;toast("Status update failed. "+friendly(e),"danger");await sync(true).catch(()=>{});render({preserve:true})}}
  async function assignRider(){toast("Smart dispatch owns rider assignment. Review the live dispatch queue instead.","danger")}
  async function cancelOrder(orderId,reason){if(!owner())return;const o=order(orderId);if(!canCancelOrder(o)){toast("In-transit orders require a documented return or support resolution, not cancellation.","danger");return}try{await cloudStatus(o,"Cancelled",reason);Object.assign(o,{status:"Cancelled",cancelReason:reason,updatedAt:Date.now()});closeSheet();await writeAudit("order.cancel",o.id,reason);toast("Order cancelled with audit reason.","success");render({preserve:true})}catch(e){toast("Cancellation failed. "+friendly(e),"danger")}}
  function slug(text){return String(text||"").toLowerCase().trim().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,48)||"restaurant"}
