      if(!newUid)throw new Error("The new owner account could not be verified.");
      if(oldOwnerIds.length===1&&oldOwnerIds[0]===newUid){throw new Error("This account is already the restaurant owner.")}
      const now=Date.now(),memberData={active:true,email,name:r.name+" Owner",permissions:{analytics:true,availability:true,dispatch:true,handover:true,menu:true,orders:true,profile:true,tracking:true},restaurantId:rid,restaurantName:r.name,role:"restaurant_owner",createdAt:now,createdBy:state.session.email},changes={};
      changes["restaurantMembers/"+rid+"/"+newUid]=memberData;
      changes["userRestaurants/"+newUid+"/"+rid]=true;
      const previousOwnerIds=oldOwnerIds.filter(oldUid=>oldUid!==newUid);
      previousOwnerIds.forEach(oldUid=>{changes["restaurantMembers/"+rid+"/"+oldUid]=null});
      // Membership is the access-control record, so it moves atomically. Clean up
