  async function completeGoogleSignIn(token){try{const d=await auth("accounts:signInWithIdp",{postBody:"id_token="+encodeURIComponent(token)+"&providerId=google.com",requestUri:"http://localhost",returnIdpCredential:true,returnSecureToken:true});setAuth(d,d.email);state.session.name=d.displayName||"";persistSession();await resolveRole()}catch(e){state.session=null;persistSession();state.role="";toast(friendly(e),"danger");state.loading=false;render();return}const synced=await enterOperations({silentFailure:true});toast(synced?"Secure Google access verified.":"Signed in. Live operations are reconnecting.",synced?"success":"warning");state.loading=false;render()}
  window.googleIdTokenReceived=completeGoogleSignIn;
  window.googleSignInFailed=function(message){state.loading=false;toast(message||"Google sign-in failed.","danger");render({preserve:true})};
  async function reset(form){const email=form.elements.email.value.trim().toLowerCase();if(!/^\S+@\S+\.\S+$/.test(email)){toast("Enter a valid email.","danger");return}try{await auth("accounts:sendOobCode",{requestType:"PASSWORD_RESET",email});closeSheet();toast("If the account exists, a reset link was requested.","success")}catch(e){toast(friendly(e),"danger")}}
  document.addEventListener("submit",event=>{const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();if(form.id==="login-form")login(form);else if(form.id==="reset-form")reset(form);else if(form.id==="restaurant-form")saveRestaurantForm(form);else if(form.id==="transfer-owner-form")transferRestaurantOwner(form);else if(form.id==="menu-item-form")saveMenuItem(form);else if(form.id==="staff-form")inviteStaff(form);else if(form.id==="rider-reward-settings-form")saveRiderRewardSettings(form);else if(form.id==="rider-reward-campaign-form")saveRiderRewardCampaign(form);else if(form.id==="promotion-form")savePromotion(form);else if(form.id==="settings-form")saveSettings(form);else if(form.id==="payment-settings-form")savePaymentPlatformConfig(form);else if(form.id==="notification-form")saveBroadcast(form);else if(form.id==="ad-form")saveLocalAd(form);else if(form.id==="cod-remittance-form")submitCodRemittance(form);else if(form.id==="rider-payout-form")submitRiderPayout(form);else if(form.id==="restaurant-settlement-form")submitRestaurantSettlement(form);else if(form.id==="cancel-form")cancelOrder(form.dataset.orderId,form.elements.reason.value);else if(form.id==="delete-restaurant-form")deleteRestaurant(form.dataset.restaurantId,form.elements.confirmation.value);else if(form.id==="reject-rider-form")rejectRider(form.dataset.riderId,form.elements.note.value)});

  async function bootstrap(){applyTheme();if(!state.session){state.route="login";render();app.setAttribute("aria-busy","false");return}state.loading=true;state.route="launch";render();try{await ensure()}catch(e){state.session=null;state.role="";persistSession();state.route="login";toast("Your operations session expired. Sign in again.","danger");state.loading=false;app.setAttribute("aria-busy","false");render();return}try{await resolveRole()}catch(e){if(e&&(e.message==="STAFF_INACTIVE"||e.message==="AUTH_REQUIRED")){state.session=null;state.role="";persistSession();state.route="login";toast("Your operations session expired. Sign in again.","danger");state.loading=false;app.setAttribute("aria-busy","false");render();return}state.error=friendly(e);if(state.session&&state.session.role){state.role=state.session.role}else{state.role="owner"}await enterOperations({silentFailure:true});state.loading=false;app.setAttribute("aria-busy","false");render();return}await enterOperations();state.loading=false;app.setAttribute("aria-busy","false");render()}
  window.addEventListener("online",()=>{state.online=true;if(state.session)refresh();else render({preserve:true})});window.addEventListener("offline",()=>{state.online=false;render({preserve:true})});document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible"&&state.session&&state.online)requestSync(true).then(()=>{if(!["restaurantEditor","menuEditor"].includes(state.route))render({preserve:true})}).catch(()=>{})});
  if(window.__SAVRIVO_ADMIN_TEST__)window.__SAVRIVO_ADMIN_SUPPORT_TEST__={state,unseenSupport,syncSupportAlarm,openSupportTicket,closeTicket,supportActivityAt,supportActivityKey,supportNeedsAttention,mergeSupportSnapshot,sync};
  if(!window.__SAVRIVO_ADMIN_TEST__)bootstrap();
